// Package genreg writes the snapshot type registry of a package: every named non-generic type that has methods
// (frames, nodes, conditions, watches) may sit in an interface field, and Load needs to know it by name.
package genreg

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// FileName is the generated file in the package directory.
const FileName = "snapshot_types_gen.go"

// Generate returns the registry source for the Go package in dir.
func Generate(dir string) ([]byte, error) {
	fset := token.NewFileSet()
	files, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		return nil, err
	}
	pkg := ""
	generic := map[string]bool{}
	withMethods := map[string]bool{}
	declared := map[string]bool{}
	for _, f := range files {
		base := filepath.Base(f)
		if strings.HasSuffix(base, "_test.go") || base == FileName {
			continue
		}
		af, err := parser.ParseFile(fset, f, nil, parser.SkipObjectResolution)
		if err != nil {
			return nil, err
		}
		pkg = af.Name.Name
		for _, d := range af.Decls {
			switch d := d.(type) {
			case *ast.GenDecl:
				for _, s := range d.Specs {
					ts, ok := s.(*ast.TypeSpec)
					if !ok {
						continue
					}
					if _, isIface := ts.Type.(*ast.InterfaceType); isIface || ts.Assign.IsValid() {
						continue
					}
					declared[ts.Name.Name] = true
					if ts.TypeParams != nil {
						generic[ts.Name.Name] = true
					}
				}
			case *ast.FuncDecl:
				if d.Recv == nil || len(d.Recv.List) == 0 {
					continue
				}
				t := d.Recv.List[0].Type
				if st, ok := t.(*ast.StarExpr); ok {
					t = st.X
				}
				switch x := t.(type) {
				case *ast.Ident:
					withMethods[x.Name] = true
				case *ast.IndexExpr, *ast.IndexListExpr:
					// methods of generic types: skipped (instantiations are not registered)
				}
			}
		}
	}
	var names []string
	for n := range withMethods {
		if declared[n] && !generic[n] {
			names = append(names, n)
		}
	}
	sort.Strings(names)
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by tools/genreg; DO NOT EDIT.\n\npackage %s\n\nimport \"aago/snapshot\"\n\n", pkg)
	b.WriteString("func init() {\n\tsnapshot.Register(\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t\t*new(%s), (*%s)(nil),\n", n, n)
	}
	b.WriteString("\t)\n}\n")
	return format.Source(b.Bytes())
}

// Write regenerates the registry file in dir.
func Write(dir string) error {
	src, err := Generate(dir)
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, FileName), src, 0o644)
}

// Stale reports whether the registry file in dir differs from what Generate returns.
func Stale(dir string) (bool, error) {
	want, err := Generate(dir)
	if err != nil {
		return false, err
	}
	have, err := os.ReadFile(filepath.Join(dir, FileName))
	if err != nil {
		return true, nil
	}
	return !bytes.Equal(want, have), nil
}
